const b = $input.first().json;
const money = (n) => '$' + Number(n || 0).toFixed(2);
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const parties = (b.partiesToday || []).map((p) =>
  `<tr><td>${esc(p.timeLabel)}</td><td>${esc(p.booking)}</td><td>${esc(p.room)}</td><td>${esc(p.packageName)}</td><td>${p.kids ?? ''}</td><td>${esc(p.stage)}</td></tr>`).join('');
const attention = (b.attention || []).map((a) => `<li>${esc(a)}</li>`).join('');
const html = `
<h2>Fun Circle: morning brief for ${esc(b.forDate)}</h2>
${b.needsAttention ? `<p style="color:#b42318"><b>Needs attention</b></p><ul>${attention}</ul>` : ''}
<h3>Parties today (${(b.partiesToday || []).length})</h3>
${parties ? `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Time</th><th>Booking</th><th>Room</th><th>Package</th><th>Kids</th><th>Stage</th></tr>${parties}</table>` : '<p>No parties today.</p>'}
<p>Parties in the next 7 days: <b>${b.partiesNext7Days}</b></p>
<h3>Follow-ups</h3>
<ul>
<li>Rebooking reminders due today: <b>${b.rebookingTasksDueToday}</b></li>
<li>Open tasks due or overdue: <b>${b.openTasksDueToday}</b></li>
<li>Unpaid orders: <b>${b.unpaidOrders}</b> (${money(b.unpaidTotal)})</li>
</ul>
<h3>Yesterday at the till (Square)</h3>
<ul>
<li>Visits with a customer attached: <b>${b.visitsYesterday}</b>, linked to a family: <b>${b.visitsYesterdayLinked}</b></li>
<li>Spend on those visits: <b>${money(b.squareSpendYesterday)}</b></li>
<li>Square sync: ${esc(b.squareSyncStatus)} (${esc(b.squareLastSync)})</li>
</ul>
<h3>AI</h3>
<ul>
<li>Claude calls yesterday: <b>${b.aiCallsYesterday}</b> (${money(b.aiCostYesterday)})</li>
<li>This month: <b>${money(b.aiCostThisMonth)}</b> of ${money(b.aiMonthlyBudget)}</li>
</ul>
<p style="color:#667085;font-size:12px">Sent by n8n from Salesforce (read-only). No customer contact details are included.</p>`;
const subject = `${b.needsAttention ? '[Attention] ' : ''}Fun Circle brief ${b.forDate}: ${(b.partiesToday || []).length} parties today, ${b.unpaidOrders} unpaid orders`;
return [{ json: { subject, html } }];
